mapper.select:
SELECT id, title, species, topic, summary, source_title, source_url, publisher, published_on, reviewed_on, review_status, reviewer_id, created_at, updated_at FROM knowledge_articles WHERE 1 = 1
AND (title LIKE CONCAT(#{keyword}, '%') OR topic LIKE CONCAT(#{keyword}, '%') OR publisher LIKE CONCAT(#{keyword}, '%'))
AND review_status = #{status}
ORDER BY updated_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM knowledge_articles WHERE 1 = 1
AND (title LIKE CONCAT(#{keyword}, '%') OR topic LIKE CONCAT(#{keyword}, '%') OR publisher LIKE CONCAT(#{keyword}, '%'))
AND review_status = #{status}

