mapper.update:
UPDATE knowledge_articles
SET review_status = #{reviewStatus},
    reviewed_on = CASE WHEN #{reviewStatus} = 'published' THEN CURDATE() ELSE reviewed_on END,
    reviewer_id = #{reviewerId}
WHERE id = #{id}
